def field(label,name,kind='text',options=None,required=False,full=False,placeholder=''):
    req=' required' if required else ''
    if options:
        control=f'<select id="{name}" name="{name}"{req}><option value="">Choose an option</option>'+''.join(f'<option>{esc(x)}</option>' for x in options)+'</select>'
    elif kind=='textarea':
        control=f'<textarea id="{name}" name="{name}" rows="4"{req} placeholder="{esc(placeholder)}"></textarea>'
    else:
        auto={'email':'email','name':'name','organisation':'organization','phone':'tel'}.get(name,'off')
        control=f'<input id="{name}" name="{name}" type="{kind}" autocomplete="{auto}"{req} placeholder="{esc(placeholder)}"'+(' min="1" max="100000"' if kind=='number' else '')+'>'
    return f'<div class="{"full" if full else ""}"><label for="{name}">{esc(label)}'+(' <span aria-hidden="true">*</span>' if required else '')+'</label>'+control+'</div>'

