def sitemap_page():
    def branch(parent):
        return '<ul class="tree-list">'+''.join(f'<li><a href="{url(s)}">{esc(t)}<code>{url(s)}</code></a>'+ (branch(s) if any(p[2]==s for p in PAGES) else '')+'</li>' for s,t,pa,k in PAGES if pa==parent)+'</ul>'
    return editorial('The complete<br>Rusetat website',f'Explore the full {len(PAGES)}-page website. Every destination, visa type and supporting page appears below.','The complete website map')+'<section class="section paper content-start"><div class="wrap"><div class="site-search"><label for="sitemap-search">Find a page</label><input id="sitemap-search" type="search" placeholder="Search pages"></div>'+branch(None)+'<p id="sitemap-empty" class="no-results" role="status" hidden>No matching pages. Try a destination, visa type or service.</p></div></section>'

def render(slug,kind):
    if kind=='home':return home()
    if kind=='travel':return travel()
    if kind=='destinations':return destinations()
    if kind=='destination':return destination(next(x for x in DESTINATIONS if x['slug']==slug.split('/')[-1]))
    if kind in ['visa-hub','sa-hub','visa-group']:return visa_hub(slug)
    if kind=='visa':return visa_detail(next(x for x in VISAS if x['slug']==slug))
    if kind=='international':return international()
    if kind=='country':return country(next(x for x in COUNTRIES if x['slug'].split('/')[-1]==slug.split('/')[-1]))
    if kind.startswith('au-pair') or kind.startswith('recruitment'):return opportunities(slug)
    if kind=='relocation':return relocation()
    if kind=='corporate':return corporate()
    if kind=='about':return about()
    if kind=='team':return team()
    if kind=='process':return process()
    if kind=='guides':return guide_index()
    if kind=='guide':return guide(next(x for x in GUIDES if x['slug']==slug.split('/')[-1]))
    if kind=='policy':return policy(slug)
    if kind=='contact':return contact()
    if kind=='faqs':return faq_page()
    if kind=='sitemap':return sitemap_page()
    raise ValueError('Unimplemented page: '+slug)

